// #d9d257 (6a993d711bef8ed807d9d257) — полная одноразовая практика (сценарий A ручной проверки 14.10): короткий звонок с ИИ-клиентом
// в «מצב תרגול», обратный таймер от 3:00, помощь «?» не прерывает звонок; после окончания — сразу официальная, практика не
// открывается снова; у бизнеса практика не в отчёте. Кейсы CALL-010, CALL-011, CALL-013.
// @call — ТРАТИТ кредиты OpenAI (до 3 минут голоса). Обычный регресс без звонков: npm test -- --grep-invert @call.
// НЕ prod-safe: создаёт кандидата «QA-AUTO-CALL-PR-…» (link_only); официальная попытка не тратится (после практики
// старт обрывается страховкой blockCallStarts). Кандидат не удаляется (правило проекта).
// Микрофон — запись разговора продавца seller-dialog.wav (с ней ИИ-клиент сам завершил практику через 66 с).
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import {
  Candidate, TXT, DIALOG_WAV, createCandidateLink, candidateRow, launchCandidate, goToPractice, tap, waitConnectingHint,
  blockCallStarts, expectOfficialScreenNoPractice, timerSeconds,
} from './support';

test.describe.configure({ mode: 'serial' });

let cand: Candidate | undefined;
let name = '';

test.afterAll(async () => {
  await cand?.browser.close();
});

test.describe('Звонок кандидата — полная одноразовая практика (#6a993d711bef8ed807d9d257)', () => {
  test('практика: «מצב תרגול», таймер от 3:00 вниз, «?» → «צריכים עזרה?» без остановки звонка; после окончания — «פרטי לקוח לשיחה», recording=null, практика не открывается (reload) @desktop @data @call #6a993d711bef8ed807d9d257', async ({ asUser }) => {
    test.setTimeout(8 * 60_000);
    const business = await asUser('business');
    name = `QA-AUTO-CALL-PR-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}», ссылка ${link} (практика пройдена; годится как QA_CALL_AFTER_PRACTICE_*), не удаляется` });

    cand = await launchCandidate({ width: 390, height: 844 }, DIALOG_WAV);
    const { page, counts } = cand;
    await goToPractice(page, link);

    const hint = waitConnectingHint(page);
    await tap(page, 'להתחיל תרגול');
    // Источник: FL-28 — подсказка начать с приветствия.
    expect(await hint).toBe(TXT.hint);

    // Источник: AC1 «שיחה קולית קצרה מול הלקוח המדומה»; короткая — таймер от 3:00.
    await expect(page.getByText('מצב תרגול')).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('button', { name: 'לסיים שיחה' })).toBeVisible();
    await expect.poll(() => timerSeconds(page), { timeout: 15_000 }).toBeLessThanOrEqual(180);
    const t0 = await timerSeconds(page);
    await expect.poll(() => timerSeconds(page), { message: 'таймер не идёт вниз', timeout: 10_000 }).toBeLessThan(t0);

    // Источник: דרישה 6 «נתיב פנייה לגורם אנושי … במסך התרגול».
    await tap(page, /עזרה|^\?$/);
    await expect(page.getByText(TXT.helpSheet)).toBeVisible();
    for (const opt of ['תקלה טכנית', 'בקשת התאמה', 'צורך נגישות']) await expect(page.getByText(opt).first()).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(page.getByText(TXT.helpSheet)).toBeHidden();
    await expect(page.getByText('מצב תרגול')).toBeVisible();
    const t1 = await timerSeconds(page);
    await expect.poll(() => timerSeconds(page), { message: 'после закрытия помощи звонок остановился', timeout: 10_000 }).toBeLessThan(t1);

    // Окончание практики: ИИ-клиент завершает после прощания или по лимиту 3:00 — ждём ответ end-candidate-attempt.
    const end = await page.waitForResponse(
      (r) => r.url().includes('/functions/v1/end-candidate-attempt') && r.request().method() === 'POST' && r.ok(),
      { timeout: 210_000 },
    );
    const body = (await end.json()) as { attempt?: { status?: string }; recording?: unknown };
    // Источник: AC2 «אינו מוערך ואינו מופיע בדוח» — практика без записи.
    expect(body.recording, 'у практики есть запись').toBeNull();
    expect(body.attempt?.status).toBe('completed');

    // Источник: AC3 «אין אפשרות לפתוח אותו מחדש והמסלול ממשיך לניסיון הרשמי».
    const blocked = await blockCallStarts(page);
    await expectOfficialScreenNoPractice(page);
    await page.reload();
    await expectOfficialScreenNoPractice(page);
    expect(counts.voice, 'голосовых сессий за тест').toBe(1);
    expect(blocked.start + blocked.voice, 'попыток старта официальной').toBe(0);
  });

  test('бизнес: после практики кандидат «בדיקה טכנית החלה», «הושלם» и «דוח» = «—» @desktop @data @call #6a993d711bef8ed807d9d257', async ({ asUser }) => {
    test.setTimeout(2 * 60_000);
    expect(name, 'нет кандидата из предыдущего теста').not.toBe('');
    const business = await asUser('business');
    // Источник: AC2 / דרישה 1; דרישה 4 «אינו נספר כניסיון רשמי».
    const row = await candidateRow(business, name);
    await expect(row).toContainText('בדיקה טכנית החלה');
    await expect(row).not.toContainText('הושלמה');
    await expect(row.getByRole('link', { name: /דוח/ })).toHaveCount(0);
  });
});
